package handlers

import (
	"log"
	"os"
	"path/filepath"
)

// reportArtifacts is scoped to exactly the files generated by one analysis.
// If cancellation, encoding, rendering, or completion fails, no sensitive,
// unregistered report files remain on disk. Existing unrelated files are
// never recursively removed.
type reportArtifacts struct {
	dir       string
	jsonPath  string
	htmlPath  string
	published bool
}

func newReportArtifacts(directory string) *reportArtifacts {
	return &reportArtifacts{
		dir:      directory,
		jsonPath: filepath.Join(directory, "results.json"),
		htmlPath: filepath.Join(directory, "report.html"),
	}
}

func (r *reportArtifacts) rollbackUnlessPublished() {
	if r.published {
		return
	}
	for _, path := range []string{r.jsonPath, r.htmlPath} {
		if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
			log.Printf("[ANALYSIS] Could not remove uncommitted report file %s: %v", path, err)
		}
	}
	// Remove only an empty directory; never recursively delete unrelated files.
	if err := os.Remove(r.dir); err != nil && !os.IsNotExist(err) {
		// A nonempty directory may contain files managed by another subsystem.
		log.Printf("[ANALYSIS] Report directory was not empty after rollback: %v", err)
	}
}
